<?phpdeclare(strict_types=1);namespace Aharutyunyan\Hw\Infrastructure\Validator\Strategy;use Aharutyunyan\Hw\Domain\Email\ValidationResult;use Aharutyunyan\Hw\Domain\Email\Validator\EmailValidatorInterface;use Aharutyunyan\Hw\Domain\Email\ValueObject\Email;final class SyntaxValidator implements EmailValidatorInterface{    public function validate(Email $email): ValidationResult    {        if (!filter_var($email->getEmail(), FILTER_VALIDATE_EMAIL)) {            return new ValidationResult(false, 'Invalid syntax');        }        return new ValidationResult(true);    }}